import { useState, useContext, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  ChevronDown, Search, Menu, X, LogIn, Mail, ArrowLeft, Wallet,
  LayoutDashboard,
  Heart,
  User,
  Package,
  CreditCard,
  BookOpen,
  HelpCircle,
  Settings,
  LogOut,
  ChevronUp
} from 'lucide-react';
import { SearchContext } from '../../context/SearchContext';
import { createUserWithEmailAndPassword, signInWithEmailAndPassword, signOut, sendEmailVerification } from 'firebase/auth';
import { auth } from '../../firebase'; // Import the configured Firebase auth
import { createUserDocument } from '../../firebase'; // Import the createUserDocument function
import { toast } from 'react-toastify'; // Import toast

import 'react-toastify/dist/ReactToastify.css'; // Import toast styles

export default function Header() {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [isEmailLoginModalOpen, setIsEmailLoginModalOpen] = useState(false);
  const [isPhoneLoginModalOpen, setIsPhoneLoginModalOpen] = useState(false);
  const [isSignupModalOpen, setIsSignupModalOpen] = useState(false);
  const [isUserDropdownOpen, setIsUserDropdownOpen] = useState(false);
  const [loggedInUser, setLoggedInUser] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loginError, setLoginError] = useState("");
  const [signupError, setSignupError] = useState("");
  const [passwordMatchError, setPasswordMatchError] = useState("");


  const handleSignup = async (e) => {
    e.preventDefault();
    const email = e.target.email.value;
    const password = e.target.password.value;
    const confirmPassword = e.target.confirmPassword.value;

    if (password !== confirmPassword) {
      setPasswordMatchError("Passwords do not match");
      return;
    }

    setIsLoading(true);

    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const user = userCredential.user;
      await createUserDocument(user); // Create user document in Firestore
      await sendEmailVerification(user); // Send email verification
      setIsSignupModalOpen(false);
      toast.success('Account created successfully! Please check your email to verify your account.');
    } catch (error) {
      console.error('Error signing up:', error.message);
      setSignupError(error.message); // Display the error to the user
    } finally {
      setIsLoading(false);
    }
  };





  const { selectedLocation, setSelectedLocation } = useContext(SearchContext);
  const navigate = useNavigate();

  useEffect(() => {
    const user = JSON.parse(sessionStorage.getItem('loggedInUser'));
    if (user) {
      setLoggedInUser(user);
      console.log('User:', user.name || user.email);
    }
  }, []);

  const toggleDropdown = () => {
    setIsDropdownOpen((prev) => !prev);
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen((prev) => !prev);
  };

  const toggleLoginModal = () => {
    setIsLoginModalOpen((prev) => !prev);
    setIsEmailLoginModalOpen(false);
    setIsPhoneLoginModalOpen(false);
  };

  const toggleEmailLoginModal = () => {
    setIsEmailLoginModalOpen((prev) => !prev);
    setIsLoginModalOpen(false);
  };

  const togglePhoneLoginModal = () => {
    setIsPhoneLoginModalOpen((prev) => !prev);
    setIsLoginModalOpen(false);
  };

  const toggleSignupModal = () => {
    setIsSignupModalOpen((prev) => !prev);
    setIsLoginModalOpen(false);
  };

  const toggleUserDropdown = () => {
    setIsUserDropdownOpen((prev) => !prev);
  };

  const handleLocationChange = (location) => {
    setSelectedLocation(location);
    setIsDropdownOpen(false);
  };

  const handleSearch = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      navigate(`/search?query=${searchQuery}&location=${selectedLocation}`);
    }
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    const email = e.target.email.value;
    const password = e.target.password.value;

    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const user = userCredential.user;
      if (!user.emailVerified) {
        throw new Error('Please verify your email before logging in.');
      }
      await createUserDocument(user); // Ensure user document is created or updated in Firestore
      setLoggedInUser({ email: user.email });
      sessionStorage.setItem('loggedInUser', JSON.stringify({ email: user.email }));
      setIsLoginModalOpen(false);
      setLoginError("");
    } catch (error) {
      setLoginError(error.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setLoggedInUser(null);
      sessionStorage.removeItem('loggedInUser');
    } catch (error) {
      console.error('Error logging out:', error.message);
    }
  };


  const handleSellClick = (e) => {
    e.preventDefault();
    if (loggedInUser) {
      navigate('/sell');
    } else {
      setIsLoginModalOpen(true);
    }
  };

  return (
    <header className="bg-white mt-0">
      <div className="container mx-auto px-4 py-4 flex items-center">
        {/* Left Section: Logo */}
        <div className="flex items-center space-x-6">
          <Link to="/">
            <img src="/k1.jpeg" alt="Logo" className="w-[120px] h-auto" />
          </Link>
          {/* Dropdown for Location */}
          <div className="relative hidden md:block">
            <button
              onClick={toggleDropdown}
              className="flex items-center text-gray-600 hover:text-gray-800 space-x-2"
            >
              <span className="text-red-600">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="w-5 h-5"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 11c0 1.657-1.343 3-3 3s-3-1.343-3-3 1.343-3 3-3 3 1.343 3 3zM12 11v3m6-6a9 9 0 11-6-6c1.488-.276 2.815 0.374 3.514 1.47M6.343 6.343l1.414 1.414M15.88 15.88a3 3 0 004.243 0 3 3 0 00.273-4.01m0 0l-1.414-1.414M18 18v3m0 0h-3m3 0a9 9 0 11-9-9m6-6v3"
                  />
                </svg>
              </span>
              {selectedLocation} <ChevronDown size={16} />
            </button>
            {/* Dropdown Menu */}
            {isDropdownOpen && (
              <div className="absolute mt-2 bg-white shadow-lg rounded-md w-48 z-50 border border-gray-200">
                <ul>
                  {['All', 'Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
                    <li
                      key={location}
                      onClick={() => handleLocationChange(location)}
                      className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                    >
                      {location}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>

        {/* Middle Section: Search Bar */}
        <div className="flex-grow mx-6">
          <form onSubmit={handleSearch} className="flex items-center bg-gray-100 rounded-md">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Find Cars, Mobile Phones and more..."
              className="flex-grow p-2 bg-transparent focus:outline-none"
            />
            <button type="submit" className="p-2 bg-red-500 text-white rounded-r-md">
              <Search size={24} />
            </button>
          </form>
        </div>

        {/* Right Section: Options */}
        <div className="flex items-center space-x-4">
          {/* Toggler for Mobile Menu */}
          <button
            onClick={toggleMobileMenu}
            className="block md:hidden text-gray-600 hover:text-gray-800"
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
          {loggedInUser && (
            <div className="relative hidden md:block">
              <button
                onClick={toggleUserDropdown}
                className="flex items-center justify-center w-12 h-12 bg-red-100 rounded-full text-red-600 font-bold"
              >
                {(loggedInUser.name || loggedInUser.email)?.charAt(0).toUpperCase()}
                {isUserDropdownOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
              </button>
              {isUserDropdownOpen && (
                <div className="absolute top-14 -left-20 bg-white shadow-lg rounded-lg w-64 z-50 border border-gray-200">
                  <div className="p-4 border-b border-gray-200">
                    <div className="text-gray-800 font-medium">Hello,</div>
                    <div className="text-gray-900 font-bold">{loggedInUser.name || loggedInUser.email}</div>
                    <button className="mt-2 w-full text-red-600 border border-red-600 py-2 rounded-lg hover:bg-red-50">
                      View and edit your profile
                    </button>
                  </div>
                  <ul className="py-2">
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <Wallet className="w-5 h-5 text-gray-500" />
                      <div>
                        <div className="font-medium">Dubizzle Wallet</div>
                        <div className="text-sm text-gray-500">Balance: EGP 0</div>
                      </div>
                    </li>
                    <li className="px-4 py-2 hover:bg-gray-100 cursor-pointer">
                      <Link to="/my-ads" className="flex items-center gap-3 hover:underline">
                        <LayoutDashboard className="w-5 h-5 text-gray-500" />
                        <span>My ads</span>
                      </Link>
                    </li>

                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <Heart className="w-5 h-5 text-gray-500" />
                      Favourites & Saved searches
                    </li>
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <User className="w-5 h-5 text-gray-500" />
                      Public Profile
                    </li>
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <Package className="w-5 h-5 text-gray-500" />
                      Buy Discounted Packages
                    </li>
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <CreditCard className="w-5 h-5 text-gray-500" />
                      Bought Packages & Billing
                    </li>
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <BookOpen className="w-5 h-5 text-gray-500" />
                      Blog
                    </li>
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <HelpCircle className="w-5 h-5 text-gray-500" />
                      Help
                    </li>
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <Settings className="w-5 h-5 text-gray-500" />
                      Settings
                    </li>
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                      <Link to="/chats" className="hover:underline">Chats</Link> {/* Add link to ChatListPage */}
                    </li>
                    <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer" onClick={handleLogout}>
                      <LogOut className="w-5 h-5 text-gray-500" />
                      Logout
                    </li>
                  </ul>
                </div>
              )}
            </div>
          )}
          {!loggedInUser && (
            <>
              <button
                className="hidden md:block text-gray-600 border-b-2 border-transparent hover:border-red-500"
                onClick={toggleSignupModal}
              >
                Sign up
              </button>
              <button
                className="hidden md:block text-gray-600 border-b-2 border-transparent hover:border-red-500"
                onClick={toggleLoginModal}
              >
                Login
              </button>
            </>
          )}
          <Link
            to="#"
            onClick={handleSellClick}
            className="hidden md:block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700"
          >
            Sell
          </Link>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden bg-white border-t">
          <div className="px-4 py-4">
            {/* Dropdown for Location */}
            <div className="relative mb-4">
              <button
                onClick={toggleDropdown}
                className="flex items-center text-gray-600 hover:text-gray-800 space-x-2"
              >
                <span>{selectedLocation}</span> <ChevronDown size={16} />
              </button>
              {isDropdownOpen && (
                <div className="absolute mt-2 bg-white shadow-lg rounded-md w-full z-50 border border-gray-200">
                  <ul>
                    {['Lefkosia', 'Magusa', 'Girne', 'Guzelyurt', 'Lefke', 'Iskele'].map((location) => (
                      <li
                        key={location}
                        onClick={() => handleLocationChange(location)}
                        className="px-4 py-2 hover:bg-gray-100 cursor-pointer"
                      >
                        {location}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
            {/* Other Options */}
            <div className="space-y-4">
              {loggedInUser ? (
                <div className="relative">
                  <button
                    onClick={toggleUserDropdown}
                    className="flex items-center justify-center w-12 h-12 bg-red-100 rounded-full text-red-600 font-bold"
                  >
                    {(loggedInUser.name || loggedInUser.email)?.charAt(0).toUpperCase()}
                    {isUserDropdownOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                  </button>
                  {isUserDropdownOpen && (
                    <div className="absolute left-0 mt-2 bg-white shadow-lg rounded-md w-48 z-50 border border-gray-200">
                      <div className="p-4 border-b border-gray-200">
                        <div className="text-gray-800 font-medium">Hello,</div>
                        <div className="text-gray-900 font-bold">{loggedInUser.name || loggedInUser.email}</div>
                        <button className="mt-2 w-full text-red-600 border border-red-600 py-2 rounded-lg hover:bg-red-50">
                          View and edit your profile
                        </button>
                      </div>
                      <ul className="py-2">
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <Wallet className="w-5 h-5 text-gray-500" />
                          <div>
                            <div className="font-medium">Dubizzle Wallet</div>
                            <div className="text-sm text-gray-500">Balance: EGP 0</div>
                          </div>
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <LayoutDashboard className="w-5 h-5 text-gray-500" />
                          My ads
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <Heart className="w-5 h-5 text-gray-500" />
                          Favourites & Saved searches
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <User className="w-5 h-5 text-gray-500" />
                          Public Profile
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <Package className="w-5 h-5 text-gray-500" />
                          Buy Discounted Packages
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <CreditCard className="w-5 h-5 text-gray-500" />
                          Bought Packages & Billing
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <BookOpen className="w-5 h-5 text-gray-500" />
                          Blog
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <HelpCircle className="w-5 h-5 text-gray-500" />
                          Help
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <Settings className="w-5 h-5 text-gray-500" />
                          Settings
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer">
                          <Link to="/chats" className="hover:underline">Chats</Link> {/* Add link to ChatListPage */}
                        </li>
                        <li className="px-4 py-2 flex items-center gap-3 hover:bg-gray-100 cursor-pointer" onClick={handleLogout}>
                          <LogOut className="w-5 h-5 text-gray-500" />
                          Logout
                        </li>
                      </ul>
                    </div>
                  )}
                </div>
              ) : (
                <>
                  <button className="text-gray-600 border-b-2 border-transparent hover:border-red-500" onClick={toggleSignupModal}>Sign up</button><br />
                  <button className="text-gray-600 border-b-2 border-transparent hover:border-red-500" onClick={toggleLoginModal}>Login</button>
                </>
              )}
              <Link
                to="#"
                onClick={handleSellClick}
                className="block bg-red-500 text-white px-4 py-2 rounded-md hover:bg-red-700"
              >
                Sell
              </Link>
            </div>
          </div>
        </div>
      )}

      {/* Categories (Optional) */}
      <div className="container mx-auto px-4 py-2 border-t border-gray-200">
        <div className="flex flex-wrap space-x-4 text-gray-600 justify-center">
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=car `)}
          >
            Vehicles
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Properties`)}
          >
            Properties
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Mobile & Tablets`)}
          >
            Mobiles & Tablets
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Jobs`)}
          >
            Jobs
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Electronics & Appliances`)}
          >
            Electronics & Appliances
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=Furniture & Decor`)}
          >
            Furniture & Decor
          </button>
          <button
            className="hover:text-gray-800 border-b-2 border-transparent hover:border-red-500"
            onClick={() => navigate(`/search?query=More Categories`)}
          >
            More Categories
          </button>
        </div>
      </div>

      {/* Login Modal */}
      {isLoginModalOpen && !isEmailLoginModalOpen && !isPhoneLoginModalOpen && !isSignupModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-md mx-4 relative">
            <button
              className="absolute top-2 right-2 text-2xl "
              onClick={toggleLoginModal} // Close modal on click
            >
              X
            </button>
            <div className="flex justify-center mb-4">
              <Link to="/">
                <img src="/k1.jpeg" alt="Logo" className="w-[120px] h-auto" />
              </Link>
            </div>
            <h2 className="text-xl font-semibold mb-4 text-center">Login into your Kibzar account</h2>

            <form onSubmit={handleLogin}> {/* Add onSubmit handler */}
              <div className="mb-4">
                <label className="block text-gray-700">Email address</label>
                <input
                  type="email"
                  name="email" // Add name attribute
                  placeholder="Enter email"
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
              </div>
              <div className="mb-4">
                <label className="block text-gray-700">Password</label>
                <input
                  type="password"
                  name="password" // Add name attribute
                  placeholder="Enter password"
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
              </div>
              {loginError && <p className="text-red-500 text-sm mb-4">{loginError}</p>} {/* Display error message */}
              <button className="w-full bg-red-500 text-white py-2 rounded-md hover:bg-red-700" disabled={isLoading}>
                {isLoading ? 'Loading...' : 'Log in'} {/* Show loading text */}
              </button>
            </form>

            <div className="text-center mt-4">
              <button
                className="text-red-500 hover:underline"
                onClick={toggleSignupModal} // Add onClick handler for signup modal
              >
                New to Kibzar? Create an account
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Email Login Modal */}
      {isEmailLoginModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-md mx-4 relative">
            <button
              className="absolute top-2 right-2 text-2xl"
              onClick={toggleEmailLoginModal} // Close modal on click
            >
              X
            </button>
            <button
              className="absolute top-2 left-2 text-2xl"
              onClick={() => {
                setIsEmailLoginModalOpen(false);
                setIsLoginModalOpen(true);
              }} // Go back to main login modal
            >
              <ArrowLeft />
            </button>
            <h2 className="text-xl font-semibold mb-4 text-center">Log in with Email</h2>
            <form>
              <div className="mb-4">
                <label className="block text-gray-700">Email address</label>
                <input
                  type="email"
                  placeholder="Enter email"
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
                <p className="text-sm text-gray-500">Please enter your e-mail address.</p>
              </div>
              <div className="mb-4">
                <label className="block text-gray-700">Password</label>
                <input
                  type="password"
                  placeholder="Enter password"
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
                <Link to="/forgot-password" className="text-sm text-red-500 hover:underline">
                  Forgot your password?
                </Link>
              </div>
              <button className="w-full bg-red-500 text-white py-2 rounded-md hover:bg-red-700">
                Log in
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Phone Login Modal */}
      {isPhoneLoginModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-md mx-4 relative">
            <button
              className="absolute top-2 right-2 text-2xl"
              onClick={togglePhoneLoginModal} // Close modal on click
            >
              X
            </button>
            <button
              className="absolute top-2 left-2 text-2xl"
              onClick={() => {
                setIsPhoneLoginModalOpen(false);
                setIsLoginModalOpen(true);
              }} // Go back to main login modal
            >
              <ArrowLeft />
            </button>
            <h2 className="text-xl font-semibold mb-4 text-center">Log in with Phone</h2>
            <form>
              <div className="mb-4">
                <label className="block text-gray-700">Phone number</label>
                <input
                  type="tel"
                  placeholder="Enter phone number"
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
                <p className="text-sm text-gray-500">Please enter your phone number.</p>
              </div>
              <div className="mb-4">
                <label className="block text-gray-700">Password</label>
                <input
                  type="password"
                  placeholder="Enter password"
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
                <Link to="/forgot-password" className="text-sm text-red-500 hover:underline">
                  Forgot your password?
                </Link>
              </div>
              <button className="w-full bg-red-500 text-white py-2 rounded-md hover:bg-red-700">
                Log in
              </button>

            </form>
            <div className="text-center mt-4">
              <Link to="/signup" className="text-red-500 hover:underline">
                New to Kibzar? Create an account
              </Link>
            </div>
          </div>
        </div>
      )}

      {/* Signup Modal */}
      {isSignupModalOpen && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-md mx-4 relative">
            <button
              className="absolute top-2 right-2 text-2xl"
              onClick={toggleSignupModal} // Close modal on click
            >
              X
            </button>
            <button
              className="absolute top-2 left-2 text-2xl"
              onClick={() => {
                setIsSignupModalOpen(false);
                setIsLoginModalOpen(true);
              }} // Go back to main login modal
            >
              <ArrowLeft />
            </button>
            <h2 className="text-xl font-semibold mb-4 text-center">Create a Kibzar account</h2>
            <form onSubmit={handleSignup}>
              <div className="mb-4">
                <label className="block text-gray-700">Email address</label>
                <input
                  type="email"
                  name="email"
                  placeholder="Enter email"
                  required
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
              </div>
              <div className="mb-4">
                <label className="block text-gray-700">Password</label>
                <input
                  type="password"
                  name="password"
                  placeholder="Enter password"
                  required
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
              </div>
              <div className="mb-4">
                <label className="block text-gray-700">Confirm Password</label>
                <input
                  type="password"
                  name="confirmPassword"
                  placeholder="Enter password again"
                  required
                  className="w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-red-500"
                />
              </div>
              {passwordMatchError && <p className="text-red-500 text-sm mb-4">{passwordMatchError}</p>}
              {signupError && <p className="text-red-500 text-sm mb-4">{signupError}</p>}
              <button
                type="submit"
                className="w-full bg-red-500 text-white py-2 rounded-md hover:bg-red-700"
                disabled={isLoading}
              >
                {isLoading ? 'Loading...' : 'Sign up'}
              </button>
            </form>
          </div>
        </div>
      )}

    </header>
  );
}
